package explorer

import (
	"fmt"

	"github.com/stellar/go-stellar-sdk/xdr"
)

// offers: the DEX's open offers (state_offers.sql). The price column is
// generated by PostgreSQL from price_n and price_d.

var offersTable = stateTable{table: table{
	name: "offers",
	key:  []string{"offer_id"},
	cols: []column{
		{"offer_id", "bigint"}, {"seller_id", "text"}, {"selling", "text"}, {"buying", "text"},
		{"amount", "bigint"}, {"price_n", "integer"}, {"price_d", "integer"}, {"flags", "integer"},
		{"sponsor", "text"}, {"last_modified_ledger", "bigint"},
	},
}}

// assetName is an asset as every table names it: native or CODE:ISSUER.
func assetName(a xdr.Asset) (string, error) {
	switch a.Type {
	case xdr.AssetTypeAssetTypeNative:
		return "native", nil
	case xdr.AssetTypeAssetTypeCreditAlphanum4, xdr.AssetTypeAssetTypeCreditAlphanum12:
		var typ, code, issuer string
		if err := a.Extract(&typ, &code, &issuer); err != nil {
			return "", err
		}
		return cleanText(code) + ":" + issuer, nil
	}
	return "", fmt.Errorf("unexpected asset type %d", a.Type)
}

func offerValues(e xdr.LedgerEntry) ([]any, error) {
	o := e.Data.MustOffer()
	seller, err := o.SellerId.GetAddress()
	if err != nil {
		return nil, err
	}
	selling, err := assetName(o.Selling)
	if err != nil {
		return nil, fmt.Errorf("offer %d selling: %w", o.OfferId, err)
	}
	buying, err := assetName(o.Buying)
	if err != nil {
		return nil, fmt.Errorf("offer %d buying: %w", o.OfferId, err)
	}
	sponsor, err := sponsorOf(e)
	if err != nil {
		return nil, err
	}
	return []any{
		int64(o.OfferId), seller, selling, buying,
		int64(o.Amount), int32(o.Price.N), int32(o.Price.D), int32(o.Flags),
		sponsor, int64(e.LastModifiedLedgerSeq),
	}, nil
}
